1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body { margin: 0; padding: 2rem 1rem; font: 16px/1.4 system-ui, sans-serif; background: #f6f6f4; color: #222; }
10	  main { max-width: 32rem; margin: 0 auto; }
11	  h1 { margin: 0 0 1rem; font-size: 1.5rem; }
12	  form { display: flex; gap: .5rem; margin-bottom: 1rem; }
13	  input { flex: 1; padding: .5rem .75rem; font: inherit; border: 1px solid #ccc; border-radius: 6px; }
14	  button { padding: .5rem .9rem; font: inherit; border: 1px solid #bbb; border-radius: 6px; background: #fff; cursor: pointer; }
15	  button:hover { background: #eee; }
16	  ul { list-style: none; margin: 0; padding: 0; }
17	  li { display: flex; align-items: center; gap: .5rem; padding: .5rem .75rem; margin-bottom: .4rem; background: #fff; border: 1px solid #e2e2e2; border-radius: 6px; }
18	  li span { flex: 1; overflow-wrap: anywhere; }
19	  li[data-completed="true"] span { text-decoration: line-through; color: #888; }
20	  li input[type="checkbox"] { flex: none; width: 1.1rem; height: 1.1rem; margin: 0; }
21	  .filters { display: flex; gap: .5rem; margin-bottom: 1rem; }
22	  .filters button[aria-pressed="true"] { background: #222; border-color: #222; color: #fff; }
23	  form input[type="date"] { flex: none; }
24	  .due { flex: none; font-size: .85rem; color: #666; }
25	  li[data-overdue="true"] { border-color: #d33; background: #fff1f0; }
26	  li[data-overdue="true"] .due { color: #b00; font-weight: 600; }
27	  form select { flex: none; padding: .5rem; font: inherit; border: 1px solid #ccc; border-radius: 6px; background: #fff; }
28	  /* [REQ-006] Priority is shown as a neutral text label only; no per-priority colours, so the overdue highlight stays readable. */
29	  /* [REQ-007] Search box and inline edit field. */
30	  .search { display: block; width: 100%; margin-bottom: 1rem; }
31	  li input.edit { padding: .2rem .4rem; }
32	  /* [REQ-009] Bulk action bar below the list. */
33	  .bulk { display: flex; gap: .5rem; margin-top: 1rem; }
34	  .priority { flex: none; font-size: .75rem; font-weight: 600; text-transform: uppercase; padding: .1rem .4rem; border-radius: 4px; background: #ececec; color: #555; }
35	</style>
36	</head>
37	<body>
38	<main>
39	  <h1>Todos</h1>
40	  <form id="todo-form">
41	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
42	    <input data-testid="todo-due" type="date" aria-label="Due date (optional)">
43	    <select data-testid="todo-priority" aria-label="Priority">
44	      <option value="low">Low</option>
45	      <option value="med" selected>Med</option>
46	      <option value="high">High</option>
47	    </select>
48	    <button data-testid="todo-add" type="submit">Add</button>
49	  </form>
50	  <input class="search" data-testid="search-input" type="search" placeholder="Search todos" aria-label="Search todos" autocomplete="off">
51	  <div class="filters" role="group" aria-label="Filter todos">
52	    <button data-testid="filter-all" type="button" data-filter="all" aria-pressed="true">All</button>
53	    <button data-testid="filter-active" type="button" data-filter="active" aria-pressed="false">Active</button>
54	    <button data-testid="filter-completed" type="button" data-filter="completed" aria-pressed="false">Completed</button>
55	  </div>
56	  <ul data-testid="todo-list"></ul>
57	  <div class="bulk" role="group" aria-label="Bulk actions">
58	    <button data-testid="bulk-mark-all" type="button">Mark all complete</button>
59	    <button data-testid="bulk-clear-completed" type="button">Clear completed</button>
60	  </div>
61	</main>
62	<script>
63	  var STORAGE_KEY = 'todos';
64	  var form = document.getElementById('todo-form');
65	  var input = document.querySelector('[data-testid="todo-input"]');
66	  var dueInput = document.querySelector('[data-testid="todo-due"]');
67	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
68	  var list = document.querySelector('[data-testid="todo-list"]');
69	  var filterButtons = document.querySelectorAll('[data-filter]');
70	  var currentFilter = 'all';
71	  var searchInput = document.querySelector('[data-testid="search-input"]');
72	  var searchTerm = '';
73	  var markAllButton = document.querySelector('[data-testid="bulk-mark-all"]');
74	  var clearCompletedButton = document.querySelector('[data-testid="bulk-clear-completed"]');
75	
76	  // [REQ-001] Load todos from localStorage; ignore malformed data.
77	  function loadTodos() {
78	    try {
79	      var parsed = JSON.parse(localStorage.getItem(STORAGE_KEY));
80	      if (!Array.isArray(parsed)) return [];
81	      // [REQ-002] Todos saved before completion existed default to active.
82	      parsed.forEach(function (t) {
83	        t.completed = t.completed === true;
84	        // [REQ-003] Drop anything that is not a plain YYYY-MM-DD string.
85	        t.due = normalizeDue(t.due);
86	        // [REQ-004] Todos saved before priorities existed default to med.
87	        t.priority = normalizePriority(t.priority);
88	      });
89	      return parsed;
90	    } catch (e) {
91	      return [];
92	    }
93	  }
94	
95	  // [REQ-001]
96	  function saveTodos() {
97	    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(todos)); } catch (e) {}
98	  }
99	
100	  // [REQ-001] Stable unique id; crypto.randomUUID is not available in every file:// context.
101	  function makeId() {
102	    if (window.crypto && typeof crypto.randomUUID === 'function') {
103	      try { return crypto.randomUUID(); } catch (e) {}
104	    }
105	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
106	  }
107	
108	  // [REQ-003] Due dates are plain YYYY-MM-DD strings, treated as local calendar dates. Never parsed through UTC.
109	  function normalizeDue(value) {
110	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : null;
111	  }
112	
113	  // [REQ-004] Priority is one of low, med, high; anything else becomes med.
114	  function normalizePriority(value) {
115	    return value === 'low' || value === 'high' ? value : 'med';
116	  }
117	
118	  // [REQ-003] Today's local calendar date as YYYY-MM-DD.
119	  function localToday(now) {
120	    function pad(n) { return (n < 10 ? '0' : '') + n; }
121	    return now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
122	  }
123	
124	  // [REQ-003] Overdue means strictly before today's local date. Same-format strings compare correctly as text.
125	  function isOverdue(due, today) {
126	    return due !== null && due < today;
127	  }
128	
129	  // [REQ-002] [REQ-005] Ordering: active todos first, completed below (DEC-003).
130	  // Within each group: high, then med, then low; insertion order within the same priority.
131	  // The todos array is kept in insertion order; bucketing by priority is stable, so it preserves that order.
132	  function orderTodos(items) {
133	    function byPriority(group) {
134	      return ['high', 'med', 'low'].reduce(function (out, p) {
135	        return out.concat(group.filter(function (t) { return t.priority === p; }));
136	      }, []);
137	    }
138	    return byPriority(items.filter(function (t) { return !t.completed; }))
139	      .concat(byPriority(items.filter(function (t) { return t.completed; })));
140	  }
141	
142	  // [REQ-002]
143	  function matchesFilter(todo, filter) {
144	    if (filter === 'active') return !todo.completed;
145	    if (filter === 'completed') return todo.completed;
146	    return true;
147	  }
148	
149	  // [REQ-007] Case-insensitive substring match on the todo text; an empty term matches everything.
150	  function matchesSearch(todo, term) {
151	    return todo.text.toLowerCase().indexOf(term.toLowerCase()) !== -1;
152	  }
153	
154	  // [REQ-001] [REQ-002] [REQ-003] [REQ-004] [REQ-007]
155	  function render() {
156	    list.textContent = '';
157	    var today = localToday(new Date());
158	    filterButtons.forEach(function (btn) {
159	      btn.setAttribute('aria-pressed', String(btn.dataset.filter === currentFilter));
160	    });
161	    // [REQ-007] Search narrows the filtered set; both must match.
162	    orderTodos(todos).filter(function (t) { return matchesFilter(t, currentFilter) && matchesSearch(t, searchTerm); }).forEach(function (todo) {
163	      var li = document.createElement('li');
164	      li.setAttribute('data-testid', 'todo-item');
165	      li.setAttribute('data-completed', String(todo.completed));
166	      li.setAttribute('data-overdue', String(isOverdue(todo.due, today)));
167	      li.setAttribute('data-priority', todo.priority);
168	      li.dataset.id = todo.id;
169	
170	      var toggle = document.createElement('input');
171	      toggle.type = 'checkbox';
172	      toggle.setAttribute('data-testid', 'todo-toggle');
173	      toggle.checked = todo.completed;
174	      toggle.setAttribute('aria-label', 'Mark "' + todo.text + '" ' + (todo.completed ? 'incomplete' : 'complete'));
175	      toggle.addEventListener('change', function () { toggleTodo(todo.id); });
176	
177	      var text = document.createElement('span');
178	      text.setAttribute('data-testid', 'todo-text');
179	      text.textContent = todo.text;
180	      text.addEventListener('dblclick', function () { startEdit(text, todo); });
181	
182	      var del = document.createElement('button');
183	      del.type = 'button';
184	      del.setAttribute('data-testid', 'todo-delete');
185	      del.textContent = 'Delete';
186	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
187	      del.addEventListener('click', function () { deleteTodo(todo.id); });
188	
189	      li.appendChild(toggle);
190	      li.appendChild(text);
191	      var priority = document.createElement('span');
192	      priority.className = 'priority';
193	      priority.textContent = todo.priority;
194	      li.appendChild(priority);
195	      if (todo.due) {
196	        var due = document.createElement('span');
197	        due.className = 'due';
198	        due.setAttribute('data-testid', 'todo-due-date');
199	        due.textContent = 'Due ' + todo.due;
200	        li.appendChild(due);
201	      }
202	      li.appendChild(del);
203	      list.appendChild(li);
204	    });
205	  }
206	
207	  // [REQ-001] [REQ-003] [REQ-004]
208	  function addTodo(rawText, rawDue, rawPriority) {
209	    var text = rawText.trim();
210	    if (!text) return;
211	    todos.push({ id: makeId(), text: text, createdAt: Date.now(), completed: false, due: normalizeDue(rawDue), priority: normalizePriority(rawPriority) });
212	    saveTodos();
213	    render();
214	  }
215	
216	  // [REQ-007] Swap the text for an input. Enter or blur commits, Escape cancels.
217	  // Blank text on commit is treated as a cancel, so editing never deletes a todo.
218	  function startEdit(textEl, todo) {
219	    var field = document.createElement('input');
220	    field.type = 'text';
221	    field.className = 'edit';
222	    field.setAttribute('data-testid', 'todo-edit-input');
223	    field.setAttribute('aria-label', 'Edit todo');
224	    field.value = todo.text;
225	    var finished = false;
226	    function finish(commit) {
227	      if (finished) return;
228	      finished = true;
229	      if (commit) editTodo(todo.id, field.value);
230	      else render();
231	    }
232	    field.addEventListener('keydown', function (e) {
233	      if (e.key === 'Enter') { e.preventDefault(); finish(true); }
234	      else if (e.key === 'Escape') { e.preventDefault(); finish(false); }
235	    });
236	    field.addEventListener('blur', function () { finish(true); });
237	    textEl.replaceWith(field);
238	    field.focus();
239	    field.select();
240	  }
241	
242	  // [REQ-007]
243	  function editTodo(id, rawText) {
244	    var text = rawText.trim();
245	    if (text) {
246	      todos.forEach(function (t) { if (t.id === id) t.text = text; });
247	      saveTodos();
248	    }
249	    render();
250	  }
251	
252	  // [REQ-001]
253	  function deleteTodo(id) {
254	    todos = todos.filter(function (t) { return t.id !== id; });
255	    saveTodos();
256	    render();
257	  }
258	
259	  // [REQ-002] Flip completion in place; the array keeps insertion order.
260	  function toggleTodo(id) {
261	    todos.forEach(function (t) { if (t.id === id) t.completed = !t.completed; });
262	    saveTodos();
263	    render();
264	  }
265	
266	  // [REQ-009] Mark every todo complete, ignoring the current filter and search.
267	  // Only the completed flag changes; the array keeps insertion order, so render() reorders per DEC-003/DEC-007/DEC-008.
268	  function markAllComplete() {
269	    todos.forEach(function (t) { t.completed = true; });
270	    saveTodos();
271	    render();
272	  }
273	
274	  // [REQ-009] Remove every completed todo, ignoring the current filter and search. Filtering keeps the remaining insertion order.
275	  function clearCompleted() {
276	    todos = todos.filter(function (t) { return !t.completed; });
277	    saveTodos();
278	    render();
279	  }
280	
281	  var todos = loadTodos();
282	
283	  // [REQ-009]
284	  markAllButton.addEventListener('click', markAllComplete);
285	  clearCompletedButton.addEventListener('click', clearCompleted);
286	
287	  filterButtons.forEach(function (btn) {
288	    btn.addEventListener('click', function () {
289	      currentFilter = btn.dataset.filter;
290	      render();
291	    });
292	  });
293	
294	  // [REQ-007]
295	  searchInput.addEventListener('input', function () {
296	    searchTerm = searchInput.value;
297	    render();
298	  });
299	
300	  form.addEventListener('submit', function (e) {
301	    e.preventDefault();
302	    addTodo(input.value, dueInput.value, priorityInput.value);
303	    input.value = '';
304	    dueInput.value = '';
305	    priorityInput.value = 'med';
306	    input.focus();
307	  });
308	
309	  // [REQ-003] Recompute overdue state when the page regains focus, in case the local date has changed.
310	  window.addEventListener('focus', render);
311	
312	  render();
313	</script>
314	</body>
315	</html>
