    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)
rep("""        t.completed = t.completed === true;
""","""        t.completed = t.completed === true;
        // [REQ-010] Search lower-cases the text, so a missing text must not break render().
        if (typeof t.text !== 'string') t.text = t.text == null ? '' : String(t.text);
""")
rep("""  // [REQ-007] Swap the text for an input. Enter or blur commits, Escape cancels.""","""  // [REQ-007] [REQ-010] Swap the text for an input. Enter or blur commits, Escape cancels.""")
rep("""  form.addEventListener('submit', function (e) {""","""  // [REQ-010] Enter in the todo input submits this form natively (it has a submit button), so no extra key handler; one would add twice.
  form.addEventListener('submit', function (e) {""")
rep("""  // [REQ-003] Recompute overdue""","""  // [REQ-010] "/" focuses search unless the user is already typing in a field.
  function isTypingTarget(el) {
    if (!el) return false;
    var tag = el.tagName;
    return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || el.isContentEditable;
  }
  document.addEventListener('keydown', function (e) {
    if (e.key !== '/' || e.ctrlKey || e.metaKey || e.altKey || isTypingTarget(e.target)) return;
    e.preventDefault();
    searchInput.focus();
    searchInput.select();
  });

  // [REQ-003] Recompute overdue""")
open(p,'w').write(s)
