const { chromium } = require('/Users/vmysla/.npm/_npx/e41f203b7505f1fb/node_modules/playwright-core');
const url = 'file:///Users/vmysla/src/product-tracebility-ab-testing/ab-study/arms/todo-rep-v2-02/treatment-v2/index.html';
const ok = (c, m) => { console.log((c ? 'PASS ' : 'FAIL ') + m); if (!c) process.exitCode = 1; };
(async () => {
  const b = await chromium.launch(); const p = await b.newPage();
  const errs = []; p.on('pageerror', e => errs.push(e.message));
  await p.goto(url);
  const T = id => p.locator(`[data-testid="${id}"]`);
  const texts = () => T('todo-text').allTextContents();
  // REQ-010 Enter adds (once)
  await T('todo-input').fill('a low'); await p.selectOption('[data-testid="todo-priority"]', 'low'); await T('todo-input').press('Enter');
  ok((await texts()).join() === 'a low', 'Enter adds exactly one todo');
  ok(await T('todo-input').inputValue() === '', 'input cleared');
  await T('todo-input').fill('b high'); await p.selectOption('[data-testid="todo-priority"]', 'high'); await T('todo-add').click();
  await T('todo-input').fill('c med'); await T('todo-due').fill('2000-01-01'); await T('todo-add').click();
  ok((await texts()).join() === 'b high,c med,a low', 'priority order');
  ok(await T('todo-item').nth(1).getAttribute('data-overdue') === 'true', 'overdue flagged');
  await T('todo-toggle').nth(0).check();
  ok((await texts()).join() === 'c med,a low,b high', 'completed below');
  await T('filter-active').click(); ok((await texts()).join() === 'c med,a low', 'active filter');
  await T('filter-completed').click(); ok((await texts()).join() === 'b high', 'completed filter');
  await T('filter-all').click();
  // REQ-010 "/" focuses search
  await p.locator('h1').click(); await p.keyboard.press('/');
  ok(await p.evaluate(() => document.activeElement.dataset.testid) === 'search-input', '/ focuses search');
  ok(await T('search-input').inputValue() === '', '/ not typed into search');
  await p.keyboard.type('med'); ok((await texts()).join() === 'c med', 'search filters');
  await T('search-input').fill(''); await T('search-input').dispatchEvent('input');
  await T('todo-input').focus(); await p.keyboard.press('/');
  ok(await T('todo-input').inputValue() === '/', '/ types normally in a field');
  await T('todo-input').fill('');
  // REQ-010 Escape cancels edit; REQ-007 Enter commits
  await T('todo-text').nth(0).dblclick(); await T('todo-edit-input').fill('changed'); await T('todo-edit-input').press('Escape');
  ok((await texts()).join() === 'c med,a low,b high', 'Escape cancels edit');
  ok(await T('todo-edit-input').count() === 0, 'edit field gone');
  await T('todo-text').nth(0).dblclick(); await p.keyboard.press('/');
  ok(await T('todo-edit-input').inputValue() === '/', '/ types normally in edit field');
  await T('todo-edit-input').fill('c edited'); await T('todo-edit-input').press('Enter');
  ok((await texts()).join() === 'c edited,a low,b high', 'Enter commits edit');
  // persistence
  await p.reload(); ok((await texts()).join() === 'c edited,a low,b high', 'persists after reload');
  // REQ-009 bulk
  await T('filter-active').click(); await T('bulk-mark-all').click(); await T('filter-all').click();
  ok((await T('todo-item').evaluateAll(l => l.every(x => x.dataset.completed === 'true'))), 'mark all ignores filter');
  await T('todo-delete').nth(0).click(); ok((await texts()).length === 2, 'delete');
  await T('bulk-clear-completed').click(); ok((await texts()).length === 0, 'clear completed');
  // legacy data without text
  await p.evaluate(() => localStorage.setItem('todos', JSON.stringify([{ id: 'x' }, { id: 'y', text: 'ok' }])));
  await p.reload(); ok((await T('todo-item').count()) === 2, 'legacy todo without text renders');
  await p.keyboard.press('/'); await p.keyboard.type('ok'); ok((await texts()).join() === 'ok', 'search with legacy data');
  ok(errs.length === 0, 'no page errors ' + errs.join('; '));
  await b.close();
})();
